package com.jnapanam.sportszone.booking.controller;import com.jnapanam.sportszone.booking.service.BookingRescheduleService;import java.util.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/booking-reschedules")public class BookingRescheduleController{private final BookingRescheduleService s;public BookingRescheduleController(BookingRescheduleService s){this.s=s;}@PostMapping("/{bookingId}")public Map<String,Object> mine(Authentication a,@PathVariable UUID bookingId,@RequestBody Map<String,String>b){return s.reschedule(UUID.fromString(a.getName()),bookingId,UUID.fromString(b.get("newSlotId")),false);}@PostMapping("/staff/{bookingId}")@PreAuthorize("hasAnyRole('SUPER_ADMIN','ADMIN','OPERATIONS')")public Map<String,Object> staff(Authentication a,@PathVariable UUID bookingId,@RequestBody Map<String,String>b){return s.reschedule(UUID.fromString(a.getName()),bookingId,UUID.fromString(b.get("newSlotId")),true);}}
